<?php

$root = dirname(__DIR__);
$pluginRoot = $root . '/plugins/PromaRepair';
$manifest = json_decode((string) file_get_contents($pluginRoot . '/plugin.json'), true);
$accounting = json_decode((string) file_get_contents($root . '/plugins/PromaAccounting/plugin.json'), true);
$intake = (string) file_get_contents($pluginRoot . '/views/intake/index.php');
$repairJs = (string) file_get_contents($pluginRoot . '/assets/js/repair-v1-1-1.js');
$repairCss = (string) file_get_contents($pluginRoot . '/assets/css/repair-v1-1-1.css');
$provider = (string) file_get_contents($pluginRoot . '/src/RepairServiceProvider.php');
$repairController = (string) file_get_contents($pluginRoot . '/src/Controllers/RepairController.php');
$customerView = (string) file_get_contents($pluginRoot . '/views/customer/index.php');
$routeCatalog = (string) file_get_contents($pluginRoot . '/src/Support/RouteCatalog.php');
$dashboard = (string) file_get_contents($pluginRoot . '/views/dashboard/index.php');
$usersController = (string) file_get_contents($root . '/controllers/UsersController.php');
$auth = (string) file_get_contents($root . '/core/Auth.php');
$pluginManager = (string) file_get_contents($root . '/core/PluginManager.php');
$service = (string) file_get_contents($pluginRoot . '/src/Services/RepairService.php');
$repo = (string) file_get_contents($pluginRoot . '/src/Repositories/RepairRepository.php');
$customerController = (string) file_get_contents($root . '/controllers/CustomersController.php');
$tests = 0;
$check = static function ($ok, $message) use (&$tests) {
    $tests++;
    if (!$ok) { fwrite(STDERR, "FAIL: {$message}\n"); exit(1); }
};

$coreVersion = require $root . '/config/version.php';
$check(is_array($manifest)
    && preg_match('/^\d+\.\d+\.\d+$/', (string) ($manifest['version'] ?? ''))
    && version_compare((string) $manifest['version'], '1.1.6', '>=')
    && (string) ($manifest['plugin_api_version'] ?? '') === (string) ($coreVersion['plugin_api'] ?? ''),
    'Repair manifest meets its v1.1.6 regression baseline and targets the current Core plugin API');
$check(in_array('migrations/2026_10_02_repair_expense_approval.sql', $manifest['migrations'] ?? [], true), 'forward migration is registered');
$check(strpos($intake, 'class="modal pr-intake-modal"') !== false && strpos($intake, 'data-repair-intake-form') !== false, 'intake is a modal form');
$check(!preg_match('/type\s*=\s*["\'](?:date|datetime-local)["\']/', $intake), 'intake has no native Gregorian date picker');
$check(strpos($intake, 'data-customer-live-search') !== false && strpos($intake, 'plugin/repair/customer-lookup') !== false, 'intake uses shared Core customer picker');
$check(strpos($intake, 'data-pattern-confirm') !== false && strpos($repairJs, 'pointerdown') !== false, 'pattern modal supports pointer drawing');
$check(strpos($intake, 'data-repair-secret-input') !== false && strpos($repairJs, "secretType?.addEventListener('change', syncSecretUI)") !== false && strpos($repairJs, 'data-secret-toggle') !== false, 'password and PIN controls become available for their selected mode');
$check(strpos($repairCss, 'width:min(1180px,calc(100vw - 48px))') !== false && strpos($repairCss, '.pr-intake-meta-grid{grid-template-columns:repeat(2') !== false, 'intake dialog overrides the Core 760px width and keeps security/date fields readable');
$requiredGetRoutes = ['plugin/repair/technician-expenses', 'plugin/repair/technician-requests', 'plugin/repair/technician-history', 'plugin/repair/technician-profile', 'plugin/repair/expense-approvals', 'customer/repairs'];
foreach ($requiredGetRoutes as $path) {
    $check((bool) array_filter($manifest['routes'] ?? [], static fn($route) => ($route['path'] ?? '') === $path && strtoupper((string) ($route['method'] ?? 'GET')) === 'GET'), 'GET route exists: ' . $path);
}
$check(strpos($routeCatalog, "'plugin/Repair/'") !== false, 'legacy capitalized aliases are generated by plugin route catalog');
$check(!(bool) array_filter($manifest['routes'] ?? [], static fn($route) => in_array($route['path'] ?? '', ['auth/login', 'users'], true)), 'plugin does not override Core login or users routes');
$technicianView = (string) file_get_contents($pluginRoot . '/views/technicians/index.php');
$check(strpos($technicianView, 'create_technician_account') !== false && strpos($technicianView, 'ساخت و ثبت تعمیرکار') !== false, 'technician registry can create an account directly');
$check(strpos($repo, 'function createTechnicianAccount') !== false && strpos($repo, "'role' => 'repair_technician'") !== false && strpos($repo, '\\Model::rollBack()') !== false, 'technician account creation is transactional and sets its staff role');
$check(strpos($provider, '$getRoutes[trim((string) $menu[\'route\'], \'/\')]') !== false, 'menu links are hidden unless their registered GET route exists');
$check(strpos($provider, 'registerRole(') !== false && strpos($pluginManager, 'function availableRoles') !== false
    && strpos($usersController, 'PluginManager::availableRoles()') !== false && strpos($auth, 'PluginManager::roleAvailable') !== false,
    'plugin registers its role through Core API and Core uses dynamic role lookup');
$check(strpos($repairController, "!\\PluginManager::isActive('proma-accounting')") !== false,
    'namespaced repair dashboard resolves the Core PluginManager class');
$check(strpos($customerView, 'data-feather="tool"') === false && strpos($customerView, 'data-feather="smartphone"') !== false,
    'customer repair empty state uses an icon available in the bundled Feather set');
$check(strpos($provider, "'icon' => 'package'") !== false && strpos($provider, "'icon' => 'tool'") === false,
    'customer repair dashboard widget uses an icon available in the bundled Feather set');
$check(strpos($dashboard, "'message-circle'") === false && strpos($dashboard, "'activity'") === false && strpos($dashboard, "'alert-circle'") === false, 'dashboard KPI names use icons available in existing Core releases');
$check(strpos($service, 'PatternLock::normalize') !== false && strpos($repo, 'SecretCipher())->encrypt') !== false, 'pattern is validated and encrypted before storage');
$check(strpos($service, 'resolveCustomer') === false && strpos($service, 'SELECT id FROM users WHERE id=? AND role=\'customer\' AND status=\'active\'') !== false, 'Repair cannot create or resolve duplicate customer records');
$check(strpos($repo, 'accounting.repair_expense.post') !== false && strpos($repo, 'accounting.repair_expense.settle') !== false, 'expense approval and settlement call the Accounting ledger hooks');
$check(strpos($repo, 'repair-expense-approve:') !== false && strpos($repo, 'repair-expense-settle:') !== false, 'ledger entries use stable idempotency keys');
$check(strpos($repo, "'status IN (\\'approved\\',\\'paid\\')'") !== false || strpos($repo, "status IN (\\'approved\\',\\'paid\\')") !== false, 'pending expenses are excluded from totals');
$check(is_array($accounting)
    && preg_match('/^\d+\.\d+\.\d+$/', (string) ($accounting['version'] ?? ''))
    && version_compare((string) $accounting['version'], '1.2.17', '>='),
    'Accounting manifest meets the v1.2.17 repair-ledger regression baseline');
$check(strpos($customerController, "'Accept'") !== false || strpos($customerController, 'HTTP_ACCEPT') !== false, 'customer creation supports async JSON responses');
$check(strpos($repo, 'WHERE r.id = ? AND r.customer_id = ? AND r.status') !== false, 'customer details enforce ownership and hide drafts');

fwrite(STDOUT, "Proma Repair release checks passed ({$tests}).\n");
